<?php
namespace App\Domain\Network\Commerce\Models;
use App\Domain\Network\Onboarding\Models\SaasOnboardingApplication;
use Illuminate\Database\Eloquent\Model; use Illuminate\Support\Str; use LogicException;
final class PlatformPaymentAttempt extends Model{protected$fillable=['tenant_id','saas_order_id','onboarding_application_id','provider','status','provider_preference_id','provider_payment_id','external_reference','amount','currency','init_point','approved_at','rejected_at'];protected$hidden=['init_point'];protected$casts=['amount'=>'decimal:2','approved_at'=>'datetime','rejected_at'=>'datetime'];protected static function booted():void{self::creating(fn(self$m)=>$m->uuid??=(string)Str::uuid());self::saving(function(self$m):void{$order=$m->saas_order_id!==null;$onboarding=$m->onboarding_application_id!==null;if($order===$onboarding)throw new LogicException('Platform payment attempt must belong exclusively to an order or onboarding.');if($order&&$m->tenant_id===null)throw new LogicException('Tenant SaaS attempts require tenant_id.');if($onboarding&&$m->tenant_id!==null)throw new LogicException('Pre-tenant attempts cannot have tenant_id.');});}public function order(){return$this->belongsTo(TenantSaasOrder::class,'saas_order_id');}public function onboarding(){return$this->belongsTo(SaasOnboardingApplication::class,'onboarding_application_id');}}
